def decimal_to_binary(decimal: int) -> str:
    if decimal < 0:
        raise ValueError("Input must be a non-negative integer.")

    binary = bin(decimal)[2:]  # Convert to binary and strip the '0b' prefix
    return f"db{binary}db"

